#include "mspa/psychology/emotions.hpp"
#include <algorithm>
#include <array>
#include <cmath>
namespace mspa {namespace {
constexpr std::array<BasicEmotion,6> all_emotions={BasicEmotion::Joy,BasicEmotion::Sadness,BasicEmotion::Fear,BasicEmotion::Anger,BasicEmotion::Anxiety,BasicEmotion::Aversion};
void merge(AgentPsychState&a,BasicEmotion k,float x,PsychTime now){if(x<=0.001f)return;auto it=std::find_if(a.emotions.begin(),a.emotions.end(),[&](const auto&e){return e.kind==k;});if(it==a.emotions.end())a.emotions.push_back({k,std::clamp(x,active_emotion_floor,1.0f),now,now});else{it->intensity=std::clamp(it->intensity+(1.0f-it->intensity)*x,active_emotion_floor,1.0f);it->updated_at=now;}}
float clamp_baseline(float x){return std::clamp(x,active_emotion_floor,0.15f);} }
float EmotionSystem::baseline(const AgentPsychState&a,BasicEmotion k)const noexcept{const float stability=std::clamp(a.personality.stability,0.0f,1.0f),empathy=std::clamp(a.personality.empathy,0.0f,1.0f),boldness=std::clamp(a.personality.boldness,0.0f,1.0f),sociability=std::clamp(a.personality.sociability,0.0f,1.0f),curiosity=std::clamp(a.personality.curiosity,0.0f,1.0f);const float positive_mood=std::max(0.0f,a.mood.valence),negative_mood=std::max(0.0f,-a.mood.valence);switch(k){case BasicEmotion::Joy:return clamp_baseline(0.02f+0.04f*stability+0.02f*sociability+0.04f*positive_mood);case BasicEmotion::Sadness:return clamp_baseline(0.01f+0.035f*(1.0f-stability)+0.03f*negative_mood);case BasicEmotion::Fear:return clamp_baseline(0.01f+0.035f*(1.0f-boldness)+0.025f*(1.0f-stability));case BasicEmotion::Anger:return clamp_baseline(0.01f+0.025f*(1.0f-empathy)+0.025f*(1.0f-stability));case BasicEmotion::Anxiety:return clamp_baseline(0.01f+0.04f*(1.0f-stability)+0.02f*(1.0f-boldness));case BasicEmotion::Aversion:return clamp_baseline(0.01f+0.02f*(1.0f-empathy)+0.02f*(1.0f-curiosity));}return active_emotion_floor;}
void EmotionSystem::ensure_baseline(AgentPsychState&a,PsychTime now)const{for(const auto kind:all_emotions){const float floor=baseline(a,kind);auto it=std::find_if(a.emotions.begin(),a.emotions.end(),[&](const auto&e){return e.kind==kind;});if(it==a.emotions.end()){a.emotions.push_back({kind,floor,now,now});continue;}if(it->started_at.ticks()==0)it->started_at=now;if(it->intensity<floor){it->intensity=floor;it->updated_at=now;}else if(it->updated_at.ticks()==0)it->updated_at=now;}}
void EmotionSystem::apply(AgentPsychState&a,const AppraisalVector&v,PsychTime now)const{ensure_baseline(a,now);if(v.relevance<=0)return;const float rel=v.relevance;const float neg=std::max(0.0f,-v.consequence),pos=std::max(0.0f,v.consequence);merge(a,BasicEmotion::Joy,rel*pos*(0.6f+0.4f*v.certainty),now);merge(a,BasicEmotion::Sadness,rel*neg*(1.0f-v.control)*(1.0f-0.4f*v.agency),now);merge(a,BasicEmotion::Fear,rel*neg*(1.0f-v.control)*(0.5f+0.5f*v.certainty),now);merge(a,BasicEmotion::Anger,rel*neg*v.agency*v.intentionality*(0.45f+0.55f*v.control),now);merge(a,BasicEmotion::Anxiety,rel*(0.55f*v.expectation_error+0.45f*(1.0f-v.certainty))*(0.5f+0.5f*neg),now);merge(a,BasicEmotion::Aversion,rel*std::max(0.0f,-v.norm_alignment)*(0.5f+0.5f*neg),now);}
void EmotionSystem::decay(AgentPsychState&a,PsychTime now,float rate)const{rate=std::max(0.0f,rate);ensure_baseline(a,now);const float stability=std::clamp(a.personality.stability,0.0f,1.0f);for(auto&e:a.emotions){if(now<e.updated_at)continue;const float floor=baseline(a,e.kind);const float elapsed=static_cast<float>(now.ticks()-e.updated_at.ticks());const float k=rate*(0.6f+0.8f*stability);e.intensity=std::max(floor,e.intensity-elapsed*k);e.updated_at=now;}}
float EmotionSystem::intensity(const AgentPsychState&a,BasicEmotion k)const noexcept{auto it=std::find_if(a.emotions.begin(),a.emotions.end(),[&](const auto&e){return e.kind==k;});return it==a.emotions.end()?baseline(a,k):std::max(it->intensity,baseline(a,k));}}
